import 'dart:convert';

TopLevel topLevelFromJson(String str) => TopLevel.fromJson(json.decode(str));

String topLevelToJson(TopLevel data) => json.encode(data.toJson());

List<Readings> readingsFromJson(String str) => List<Readings>.from(json.decode(str).map((x) => Readings.fromJson(x)));

String readingsToJson(List<Readings> data) => json.encode(List<dynamic>.from(data.map((x) => x.toJson())));

class TopLevel {
    final String id;
    final DateTime when;
    final DateTime day;
    final dynamic nothing;
    final List<dynamic> empty;
    final List<dynamic> values;
    final List<Item> items;
    final int topLevelToString;
    final String topLevelRuntimeType;

    TopLevel({
        required this.id,
        required this.when,
        required this.day,
        required this.nothing,
        required this.empty,
        required this.values,
        required this.items,
        required this.topLevelToString,
        required this.topLevelRuntimeType,
    });

    factory TopLevel.fromJson(Map<String, dynamic> json) => TopLevel(
        id: ((String x) => RegExp(r'^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$').hasMatch(x) ? x : throw FormatException('Invalid UUID'))(json["id"]),
        when: DateTime.parse(json["when"]),
        day: DateTime.parse(json["day"]),
        nothing: (json.containsKey("nothing") ? json["nothing"] : throw FormatException('Missing required property')),
        empty: List<dynamic>.from(json["empty"].map((x) => x)),
        values: List<dynamic>.from(json["values"].map((x) => x)),
        items: List<Item>.from(json["items"].map((x) => Item.fromJson(x))),
        topLevelToString: json["toString"],
        topLevelRuntimeType: json["runtimeType"],
    );

    Map<String, dynamic> toJson() => {
        "id": id,
        "when": when.toIso8601String(),
        "day": "${day.year.toString().padLeft(4, '0')}-${day.month.toString().padLeft(2, '0')}-${day.day.toString().padLeft(2, '0')}",
        "nothing": nothing,
        "empty": List<dynamic>.from(empty.map((x) => x)),
        "values": List<dynamic>.from(values.map((x) => x)),
        "items": List<dynamic>.from(items.map((x) => x.toJson())),
        "toString": topLevelToString,
        "runtimeType": topLevelRuntimeType,
    };
}

class Item {
    final String name;
    final int? count;
    final DateTime? at;
    final List<int>? extra;

    Item({
        required this.name,
        required this.count,
        this.at,
        this.extra,
    });

    factory Item.fromJson(Map<String, dynamic> json) => Item(
        name: json["name"],
        count: (json.containsKey("count") ? json["count"] : throw FormatException('Missing required property')),
        at: json["at"] == null ? null : DateTime.parse(json["at"]),
        extra: json["extra"] == null ? null : List<int>.from(json["extra"]!.map((x) => x)),
    );

    Map<String, dynamic> toJson() => {
        "name": name,
        "count": count,
        "at": at == null ? null : "${at!.year.toString().padLeft(4, '0')}-${at!.month.toString().padLeft(2, '0')}-${at!.day.toString().padLeft(2, '0')}",
        "extra": extra == null ? null : List<dynamic>.from(extra!.map((x) => x)),
    };
}

