@freezed
abstract class TopLevel with _$TopLevel {
    const factory TopLevel({
        @JsonKey(name: "id")
        required String id,
        @JsonKey(name: "when")
        required DateTime when,
        @JsonKey(name: "day")
        required DateTime day,
        @JsonKey(name: "nothing")
        required dynamic nothing,
        @JsonKey(name: "empty")
        required List<dynamic> empty,
        @JsonKey(name: "values")
        required List<dynamic> values,
        @JsonKey(name: "items")
        required List<Item> items,
        @JsonKey(name: "toString")
        required int topLevelToString,
        @JsonKey(name: "runtimeType")
        required String topLevelRuntimeType,
    }) = _TopLevel;

    factory TopLevel.fromJson(Map<String, dynamic> json) => _$TopLevelFromJson(json);
}

